-- J4c-4c — VERIFICAÇÃO (somente leitura; só nomes e contagens). Esperado: 29 policies (1 para visitante: avisos gerais); visitante sem escrita; função segura; dados iguais ao registro.
select 'policies nas 10 tabelas (esperado 29)' as item, (select count(*) from pg_policies where schemaname = 'public' and tablename in ('feedbacks', 'notifications', 'pushes', 'push_reads', 'joiner_storage', 'joiner_conferencias', 'joiner_updates', 'envio_rounds', 'envio_requests', 'confirmacoes'))::text as valor
union all select 'policies para visitante/PUBLIC (esperado 1: avisos gerais)', (select count(*) from pg_policies where schemaname = 'public' and tablename in ('feedbacks', 'notifications', 'pushes', 'push_reads', 'joiner_storage', 'joiner_conferencias', 'joiner_updates', 'envio_rounds', 'envio_requests', 'confirmacoes') and ('anon' = any(roles) or 'public' = any(roles)))::text
union all select 'RLS ligado nas 10 tabelas (esperado 10)', (select count(*) from pg_class c where c.relnamespace = 'public'::regnamespace and c.relname in ('feedbacks', 'notifications', 'pushes', 'push_reads', 'joiner_storage', 'joiner_conferencias', 'joiner_updates', 'envio_rounds', 'envio_requests', 'confirmacoes') and c.relrowsecurity)::text
union all select 'visitante com privilégio fora de pushes/SELECT (esperado false)',
       (select coalesce(bool_or(has_table_privilege('anon', 'public.' || x, 'SELECT') or has_table_privilege('anon', 'public.' || x, 'INSERT') or has_table_privilege('anon', 'public.' || x, 'UPDATE') or has_table_privilege('anon', 'public.' || x, 'DELETE')), false)::text
          from unnest(array['feedbacks', 'notifications', 'push_reads', 'joiner_storage', 'joiner_conferencias', 'joiner_updates', 'envio_rounds', 'envio_requests', 'confirmacoes']) x)
union all select 'visitante escreve em pushes (esperado false)', (has_table_privilege('anon', 'public.pushes', 'INSERT') or has_table_privilege('anon', 'public.pushes', 'UPDATE') or has_table_privilege('anon', 'public.pushes', 'DELETE'))::text
union all select 'gatilhos de campos ligados (esperado 4)', (select count(*) from pg_trigger where tgname = 'trg_j4c4c_protege' and tgenabled = 'O')::text
union all select 'envio_entrar_round segura e fechada ao visitante (esperado true)', (select (p.prosecdef and p.proconfig = array['search_path=""'] and not has_function_privilege('anon', p.oid, 'EXECUTE'))::text from pg_proc p where p.oid = 'public.envio_entrar_round(text)'::regprocedure)
union all select 'impressão antes | agora (feedbacks)', coalesce((select detalhe from emergencia.c0b_estado_anterior where etapa = 'J4c-4c' and objeto = 'impressão feedbacks'), 'sem registro') || ' | ' || (select 'linhas=' || count(*) || ' md5=' || md5(coalesce(string_agg(id::text || coalesce(status_txt, ''), ',' order by id::text), '')) from (select id, 'x' as status_txt from public.feedbacks) q)
union all select 'estado registrado (linhas J4c-4c, esperado >= 20)', (select count(*) from emergencia.c0b_estado_anterior where etapa = 'J4c-4c')::text;
